def read_number():
    while True:
        try:
            text = input("Number or quit: ").strip().lower()
        except EOFError:
            return None
        if text == "quit":
            return None
        try:
            return float(text)
        except ValueError:
            print("Try a number")
print(read_number())

def countdown(start):
    values = []
    while start > 0:
        values.append(start)
        start -= 1
    return values

